import React, { useEffect } from 'react';

// Modal genérico usado por todas las pantallas de admin (Usuarios, Mesas,
// Categorías, Modificadores, Menú) para que crear/editar se vea siempre igual,
// en vez de formularios sueltos empujando el contenido de la página.
const Modal = ({ title, onClose, children, maxWidth = 560 }) => {
  useEffect(() => {
    const handleEsc = (e) => { if (e.key === 'Escape') onClose(); };
    window.addEventListener('keydown', handleEsc);
    return () => window.removeEventListener('keydown', handleEsc);
  }, [onClose]);

  return (
    <div
      style={{
        position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
        background: 'rgba(0,0,0,0.8)', zIndex: 600,
        display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 20,
      }}
      onClick={onClose}
    >
      <div
        className="card animate-fade-in"
        style={{ maxWidth, width: '100%', maxHeight: '85vh', overflowY: 'auto' }}
        onClick={(e) => e.stopPropagation()}
      >
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
          <h3 style={{ color: '#e2e8f0' }}>{title}</h3>
          <button
            type="button"
            onClick={onClose}
            style={{ background: '#334155', color: '#e2e8f0', border: 'none', borderRadius: '50%', width: 32, height: 32, cursor: 'pointer', flexShrink: 0 }}
          >
            ✕
          </button>
        </div>
        {children}
      </div>
    </div>
  );
};

export default Modal;
